/**
 * FAQ page.
 * @module src/routes/faq
 */

import React, {
    useRef,
} from 'react';
import {
    func,
} from 'prop-types';

import * as styles from './index.less';
import FAQMarkdown from './faq.md';

/**
 * Details toggle function.
 * @callback DetailsToggleFn
 * @param {Event} event - The event.
 * @param {boolean} isOpen - True to open, false to close.
 */

/**
 * Details controls component.
 * @param {object} props - The component's props.
 * @param {DetailsToggleFn} props.toggle - Details toggle function.
 * @returns {React.ReactElement} The component's elements.
 */
function DetailsControls({ toggle }) {
    return (
        <div className={styles.detailsControls}>
            <button
                className={styles.success}
                onClick={(event) => toggle(event, true)}
            >
                + Show all
            </button>
            <button
                className={styles.danger}
                onClick={(event) => toggle(event, false)}
            >
                - Hide all
            </button>
        </div>
    );
}

DetailsControls.propTypes = {
    toggle: func.isRequired,
};

/**
 * FAQ page component.
 * @returns {React.ReactElement} The component's elements.
 */
export default function FAQ() {
    const faqMarkdownRef = useRef(null);

    /**
     * Toggle the details.
     * @param {Event} event - The event.
     * @param {boolean} isOpen - True to open, false to close.
     */
    function toggle(event, isOpen) {
        faqMarkdownRef.current.querySelectorAll('details').forEach((elem) => {
            if (isOpen) {
                elem.setAttribute('open', '');
            } else {
                elem.removeAttribute('open');
            }
        });
    }

    return (
        <>
            <h1>
                Myths, facts, and frequently-asked questions
            </h1>
            <DetailsControls toggle={toggle} />
            <FAQMarkdown ref={faqMarkdownRef} />
            <DetailsControls toggle={toggle} />
        </>
    );
}
